TASKS=[
 ('count-even','Count even readings','Return the number of even integers in nums. Zero and negative even values count. Count occurrences, not distinct values. An empty array returns 0.',lambda a:sum(n%2==0 for n in a),{'python':'def solve(nums):\n    return sum(1 for n in nums if n % 2 == 0)','javascript':'function solve(nums) { return nums.filter(n => n % 2 === 0).length; }','java':'class Solution { public static Object solve(int[] nums) { int count=0; for(int n:nums)if(n%2==0)count++; return count; } }'}),
 ('largest-reading','Find the largest reading','Return the largest integer in nums without changing the array. Values may all be negative. Return null for an empty array. Do not return 0 merely because no positive value exists.',lambda a:max(a) if a else None,{'python':'def solve(nums):\n    return max(nums) if nums else None','javascript':'function solve(nums) { if(!nums.length)return null; let best=nums[0]; for(const n of nums)if(n>best)best=n; return best; }','java':'class Solution { public static Object solve(int[] nums) { if(nums.length==0)return null; int best=nums[0];for(int n:nums)if(n>best)best=n; return best; } }'}),
 ('equal-neighbors','Count equal neighboring pairs','Return the number of adjacent index pairs with equal values. For [4,4,4], the pairs at indexes (0,1) and (1,2) give 2. Equal values separated by another value do not form a pair. Empty and single-element arrays return 0.',lambda a:sum(a[i]==a[i-1] for i in range(1,len(a))),{'python':'def solve(nums):\n    return sum(nums[i] == nums[i-1] for i in range(1, len(nums)))','javascript':'function solve(nums) { let count=0;for(let i=1;i<nums.length;i++)if(nums[i]===nums[i-1])count++;return count; }','java':'class Solution { public static Object solve(int[] nums) { int count=0;for(int i=1;i<nums.length;i++)if(nums[i]==nums[i-1])count++;return count; } }'})]
