import sqlite3
def expected(dataset,query):
 db=sqlite3.connect(':memory:');db.executescript(dataset);out=[list(r) for r in db.execute(query)];db.close();return out
for slug,title,statement,comps,ref in [
 ('contact-directory','Build a contact directory','Return id, name and contact for every customer, ordered by id. contact is the email, or the literal string unknown when email is NULL. Preserve different customers that share a name.',['null_handling','duplicates'],"SELECT id,name,COALESCE(email,'unknown') AS contact FROM customers ORDER BY id"),
 ('matched-orders','Match orders to customer names','Return order id, customer name and amount for strictly positive orders with a matching customer. Exclude unmatched or NULL customer IDs. Keep separate purchases even if amounts match. Order by order id.',['joins','filtering','duplicates'],'SELECT o.id,c.name,o.amount FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.amount>0 ORDER BY o.id'),
 ('customer-order-counts','Count purchases by customer','Return customer_id and purchase_count for each non-NULL customer_id in orders. Count each order row, including repeated amounts and NULL amounts. Do not list customers with no order rows. Order by customer_id.',['aggregation','duplicates','null_handling'],'SELECT customer_id,COUNT(*) AS purchase_count FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id ORDER BY customer_id')]:
 write(dict(slug='sql-beginner-'+slug,family='sql.'+slug+'.beginner',skill='sql',type='sql',level='beginner',minutes=6,title=title,statement=statement,competencies=comps,language='sql',schema=SCHEMA,sample_rows={'customers':[[1,'Ada','a@example.test'],[2,'Lin',None],[3,'Ada','c@example.test']],'orders':[[1,1,12],[2,1,12],[3,3,0]]},starter='SELECT\n-- Choose the requested columns and tables.\n',reference=ref,tests=[dict(label=['Sample shop','Missing values','Repeated events','No orders'][i],dataset=SCHEMA+data,expected=expected(SCHEMA+data,ref),visibility='sample' if i==0 else 'hidden',competencies=comps) for i,data in enumerate(DATA)],hints=['Keep the requested output column order.','Use IS NULL or COALESCE when the contract mentions missing values.']))
# Each Spring scenario has a different statement and answer set at its declared level.
def scenario(skill,level,slug,title,context,comps,questions,minutes=None):
 qrows=[];answers={};rationale=[]
 for i,(prompt,correct,wrong1,wrong2,why) in enumerate(questions):
  qid='q'+str(i+1);options=[{'id':qid+'-'+str(n+1),'text':value} for n,value in enumerate([correct,wrong1,wrong2])]
  qrows.append({'id':qid,'prompt':prompt,'options':options});answers[qid]=qid+'-1';rationale.append(why)
 c=dict(slug=f'{skill}-{level}-{slug}',family=f'{skill}.{slug}.{level}',skill=skill,type='scenario',level=level,minutes=minutes or {'beginner':4,'intermediate':6,'advanced':8}[level],title=title,statement=context,competencies=comps,questions=qrows,answers=answers,answer_rationale=rationale,hints=['Identify the requirement and the boundary where it must hold.','Compare the failure behavior of every choice.'])
 if level!='beginner':c.update(explanation_prompt='Explain why your choice fits this scenario and how you would verify its behavior.',explanation_rubric=['Names the relevant technical boundary.','Connects the choice to the failure or correctness requirement.','Gives a concrete verification step.'])
 write(c)
scenario('spring-boot','beginner','request-dto','Read and validate an API request','A new POST /profiles endpoint receives JSON. The candidate must identify basic request binding and how invalid input reaches the HTTP client.',['rest_apis','validation'],[
 ('Which parameter binding reads the JSON body?','A request DTO annotated with @RequestBody','A @PathVariable without a matching route variable','A JPA entity field annotated @GeneratedValue','@RequestBody binds the request representation to the DTO.'),
 ('How should a missing required name be rejected?','Put @NotBlank on the DTO field and use @Valid at the request boundary','Use @Autowired on the name field','Return success and assume the database fixes it later','Boundary validation gives an actionable client error before processing.')])
scenario('spring-boot','beginner','repository-service','Connect a service and repository','An endpoint needs to save a small customer record. Choose basic dependency injection and repository operations rather than manually constructing Spring-managed objects.',['services','persistence'],[
 ('How should the controller receive its service?','Use constructor injection of the managed service','Create new Service() in each request','Store it in a mutable static global initialized by the client','Constructor injection lets Spring provide configured dependencies.'),
 ('Which repository operation persists a new mapped entity?','Call the repository save operation through the service','Call findById and assume it inserts a row','Serialize the entity to a log file instead of the configured database','save expresses the persistence operation.')])
scenario('spring-boot','beginner','failure-boundary','Handle a missing record and failed write','A small service reads a record by ID and performs two database updates. Clients need a deliberate missing-record response and the writes must succeed together.',['transactions','exceptions'],[
 ('A record does not exist. What should the HTTP boundary do?','Map the domain not-found case to a deliberate 404 response','Return a Java stack trace with status 200','Retry forever without returning a response','A deliberate not-found mapping makes the contract explicit.'),
 ('Where should the shared unit of work be declared?','At the managed service operation with @Transactional','Only on the response DTO','On a local variable after the first database commit','The service boundary groups the writes into one transaction.')])
scenario('spring-boot','intermediate','patch-contract','Preserve PATCH field semantics','PATCH /profiles accepts optional fields. A missing field means leave it unchanged, while an explicit clear action must remain distinguishable. Invalid changes should fail before business writes.',['rest_apis','validation'],[
 ('How should missing and explicit clearing be represented?','Use a patch representation that tracks field presence separately from value','Treat every missing field as a request to erase it','Reuse a full replacement DTO and overwrite every field','Presence is needed to distinguish no change from explicit clear.'),
 ('When should cross-field validation run?','Validate the proposed merged state before committing the update','Only validate field names after sending success','Skip validation for PATCH requests','Validating the resulting state preserves business constraints.')])
scenario('spring-boot','intermediate','concurrent-stock','Prevent lost stock updates','Two requests read the same stock count and each writes a decremented value. The application must detect conflicting updates and preserve the stock invariant.',['persistence','transactions'],[
 ('Which mechanism detects a stale entity update?','Use an optimistic version field and handle the conflict','Keep stock in an unsynchronized controller field','Use a larger HTTP timeout','Optimistic version checks reject a write based on stale state.'),
 ('How should a rejected concurrent update be handled?','Reload/retry under a bounded policy or return a deliberate conflict','Return success without checking the database result','Silently overwrite the newer value','A bounded conflict policy preserves correctness and client semantics.')])
scenario('spring-boot','intermediate','service-validation','Keep business rules at the service boundary','An order can be created by HTTP and by a scheduled job. Both entry points must apply the same credit-limit rule and return safe domain errors.',['services','validation','exceptions'],[
 ('Where should the shared credit-limit rule run?','In the application/service boundary used by both entry points','Only in the HTTP controller','Only in browser JavaScript','A shared service rule covers every caller.'),
 ('What should a failed business rule expose over HTTP?','A deliberate client-facing error contract without internal stack traces','The database password and raw SQL exception','A success status containing an unstructured exception string','Domain error mapping makes the failure actionable without disclosing internals.')])
scenario('spring-boot','intermediate','async-context','Keep asynchronous work durable','An endpoint returns 202 for a background export. The export needs a durable job ID, a clear status response and its own correctly scoped dependencies.',['rest_apis','services','persistence','transactions','exceptions'],[
 ('What makes an accepted export recoverable after restart?','Persist the job before returning its ID and process it with retry handling','Start an untracked thread and forget the request','Store only an in-memory boolean in the controller','Durable state preserves the accepted work across restarts.'),
 ('How should the worker use persistence?','Start its own unit of work and store success or failure state','Reuse a closed request EntityManager on another thread','Assume the request transaction stays open after the response','A worker needs a valid unit of work and explicit terminal state.')])
